import { test } from "node:test";
import assert from "node:assert/strict";
import { InMemoryQueue } from "../src/queue/broker.ts";
import { ChartStore, type LabResult } from "../src/labs/results.ts";
import { LabResultsConsumer } from "../src/labs/resultsConsumer.ts";
import { redrive } from "../src/labs/redrive.ts";

const potassium = (mrn: string) => `${mrn}|2823-3|4.1|mmol/L|2026-11-19T07:42:00Z`;

function setup(registered: string[] = ["MRN-100"]) {
    const main = new InMemoryQueue();
    const dlq = new InMemoryQueue();
    const charts = new ChartStore();
    registered.forEach((m) => charts.register(m));
    return { main, dlq, charts, consumer: new LabResultsConsumer(main, dlq, charts, 3) };
}

async function dlqContents(dlq: InMemoryQueue) {
    const msgs = await dlq.receive(100);
    for (const m of msgs) await dlq.nack(m.receipt);
    return msgs;
}

test("a valid result is filed into the patient's chart", async () => {
    const { main, charts, consumer } = setup();
    await main.send(potassium("MRN-100"));
    await consumer.drain();
    assert.deepEqual(charts.resultsFor("MRN-100").map((r) => [r.testCode, r.value]), [["2823-3", 4.1]]);
    assert.equal(main.depth(), 0);
});

test("a malformed message goes straight to the dead-letter queue", async () => {
    const { main, dlq, consumer } = setup();
    await main.send("MRN-100|2823-3|high");
    await consumer.drain();
    const [parked] = await dlqContents(dlq);
    assert.match(parked.attributes["x-error"], /MalformedResultError/);
    assert.equal(consumer.stats.retried, 0);
});

test("a result for a patient who isn't registered yet is retried and then filed", async () => {
    const { main, dlq, charts, consumer } = setup([]);
    const add = charts.addResult.bind(charts);
    let calls = 0;
    charts.addResult = async (r: LabResult) => {
        if (++calls === 2) charts.register("MRN-200"); // registration lands while we retry
        return add(r);
    };
    await main.send(potassium("MRN-200"));
    await consumer.drain();
    assert.equal(charts.resultsFor("MRN-200").length, 1);
    assert.equal(dlq.depth(), 0);
});

test("a result that keeps failing is dead-lettered after 3 attempts", async () => {
    const { main, dlq, consumer } = setup();
    await main.send(potassium("MRN-999"));
    await consumer.drain().catch((err) => console.log("drain:", err.message, consumer.stats));
    assert.equal(dlq.depth(), 1);
    assert.deepEqual(consumer.stats, { charted: 0, retried: 2, deadLettered: 1 });
});

test("a poison message doesn't keep the results behind it waiting", async () => {
    const { main, charts, consumer } = setup();
    await main.send(potassium("MRN-999"));
    for (let i = 0; i < 5; i++) await main.send(potassium("MRN-100"));
    await consumer.drain();
    assert.equal(charts.resultsFor("MRN-100").length, 5);
    assert.equal(main.depth(), 0);
});

test("a dead-lettered message keeps its body and records why and how often it failed", async () => {
    const { main, dlq, consumer } = setup();
    const id = await main.send(potassium("MRN-999"), { "x-sending-facility": "NORTH-LAB" });
    await consumer.drain();
    const [parked] = await dlqContents(dlq);
    assert.equal(parked.body, potassium("MRN-999"));
    assert.deepEqual(parked.attributes, {
        "x-sending-facility": "NORTH-LAB",
        "x-original-id": id,
        "x-error": "UnknownPatientError: no chart for MRN MRN-999",
        "x-attempts": "3",
    });
});

test("once the patient is registered, redriving the DLQ files the parked result", async () => {
    const { main, dlq, charts, consumer } = setup();
    await main.send(potassium("MRN-300"));
    await main.send("garbage");
    await consumer.drain();
    charts.register("MRN-300");
    const moved = await redrive(dlq, main, (body) => body.startsWith("MRN-300|"));
    assert.equal(moved, 1);
    await consumer.drain();
    assert.equal(charts.resultsFor("MRN-300").length, 1);
    assert.equal(dlq.depth(), 1);
});
